layer.onloaded:
js(
            (function () {

                var mode =
                    new URLSearchParams(location.search).get('mode')
                    || 'user';

                var id =
                    new URLSearchParams(location.search).get('id')
                    || 'demo123';

                document.title = mode.toUpperCase() + ' - ' + id;

                alert(
                    'MODE = ' + mode +
                    '\nID = ' + id
                );

            })();
        );
